@page "/board"
@using sv_38920f7b6936434e8a222b4cef672f65.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (_loading)
{
    <div class="alert alert-info">Loading tasks…</div>
}
else if (_error is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="stats-bar">
        <span class="badge bg-secondary">Total: @_allTasks.Count</span>
        <span class="badge bg-primary">To Do: @GetColumnTasks("To Do").Count</span>
        <span class="badge bg-warning text-dark">In Progress: @GetColumnTasks("In Progress").Count</span>
        <span class="badge bg-success">Done: @GetColumnTasks("Done").Count</span>
        <span class="badge bg-danger">Overdue: @_allTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="_searchTerm" @bind:event="oninput" />
    </div>

    <!-- Board columns -->
    <div class="board">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            var columnTotal = GetColumnTasks(column).Count;
            <div class="board-column">
                <div class="column-header">
                    <h5>@column <span class="badge bg-light text-dark">@columnTotal</span></h5>
                </div>

                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="card task-card mb-2">
                            <div class="card-body p-2">
                                <h6 class="card-title mb-1">@task.Title</h6>
                                <p class="card-text mb-1 text-muted small">@task.Assignee</p>
                                <div class="d-flex justify-content-between align-items-center mb-1">
                                    <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                </div>
                                <div class="d-flex gap-1">
                                    @if (GetColumnIndex(column) > 0)
                                    {
                                        <button class="btn btn-sm btn-outline-secondary"
                                                disabled="@_operationInProgress"
                                                @onclick="() => MoveTaskAsync(task.Id, _columns[GetColumnIndex(column) - 1])">
                                            ← Move Left
                                        </button>
                                    }
                                    @if (GetColumnIndex(column) < _columns.Length - 1)
                                    {
                                        <button class="btn btn-sm btn-outline-secondary"
                                                disabled="@_operationInProgress"
                                                @onclick="() => MoveTaskAsync(task.Id, _columns[GetColumnIndex(column) + 1])">
                                            Move Right →
                                        </button>
                                    }
                                </div>
                            </div>
                        </div>
                    }
                </div>

                @if (_showForm.TryGetValue(column, out var show) && show)
                {
                    <div class="card mt-2">
                        <div class="card-body p-2">
                            <h6 class="card-title">New Task</h6>
                            <input type="text" class="form-control form-control-sm mb-1" placeholder="Title"
                                   @bind="_formTitle" />
                            <input type="text" class="form-control form-control-sm mb-1" placeholder="Assignee"
                                   @bind="_formAssignee" />
                            <select class="form-select form-select-sm mb-1" @bind="_formPriority">
                                <option value="High">High</option>
                                <option value="Medium">Medium</option>
                                <option value="Low">Low</option>
                            </select>
                            <input type="date" class="form-control form-control-sm mb-2"
                                   @bind="_formDueDate" />
                            <div class="d-flex gap-1">
                                <button class="btn btn-sm btn-primary" disabled="@_operationInProgress"
                                        @onclick="() => SaveTaskAsync(column)">Save</button>
                                <button class="btn btn-sm btn-outline-secondary"
                                        @onclick="() => CancelForm(column)">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-sm btn-outline-primary mt-2 w-100"
                            @onclick="() => ShowAddForm(column)">+ Add Task</button>
                }
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchTerm = string.Empty;
    private bool _operationInProgress;

    // Per-column add-form visibility
    private readonly Dictionary<string, bool> _showForm = new();

    // Form fields
    private string _formTitle = string.Empty;
    private string _formAssignee = string.Empty;
    private string _formPriority = "Medium";
    private DateTime _formDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
    {
        var tasks = GetColumnTasks(status);
        if (!string.IsNullOrWhiteSpace(_searchTerm))
        {
            tasks = tasks.Where(t => t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
        }
        return tasks;
    }

    private int GetColumnIndex(string column) => Array.IndexOf(_columns, column);

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        try
        {
            _operationInProgress = true;
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);

            var idx = _allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _operationInProgress = false;
        }
    }

    private void ShowAddForm(string column)
    {
        // Reset form fields
        _formTitle = string.Empty;
        _formAssignee = string.Empty;
        _formPriority = "Medium";
        _formDueDate = DateTime.Today.AddDays(7);

        // Close any other open forms and open this one
        foreach (var key in _columns)
            _showForm[key] = false;

        _showForm[column] = true;
    }

    private void CancelForm(string column)
    {
        _showForm[column] = false;
    }

    private async Task SaveTaskAsync(string column)
    {
        if (string.IsNullOrWhiteSpace(_formTitle))
            return;

        try
        {
            _operationInProgress = true;
            var created = await TaskService.CreateTaskAsync(_formTitle, _formAssignee, _formPriority, _formDueDate);
            // The service creates with default status; override to match target column
            _allTasks.Add(created with { Status = column });

            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
            }

            _showForm[column] = false;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _operationInProgress = false;
        }
    }
}

.stats-bar {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
    margin-bottom: 1rem;
}

.stats-bar .badge {
    font-size: 0.9rem;
    padding: 0.5em 0.75em;
}

.board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    min-width: 0;
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
}

.column-header h5 {
    margin: 0 0 0.5rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.column-body {
    flex: 1;
    min-height: 3rem;
}

.task-card {
    border-left: 3px solid #6c757d;
}

.priority-high {
    background-color: #dc3545 !important;
    color: #fff;
}

.priority-medium {
    background-color: #ffc107 !important;
    color: #212529;
}

.priority-low {
    background-color: #198754 !important;
    color: #fff;
}

