.stats-bar {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
    margin-bottom: 1rem;
}

.stats-bar .badge {
    font-size: 0.9rem;
    padding: 0.5em 0.75em;
}

.board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    min-width: 0;
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
}

.column-header h5 {
    margin: 0 0 0.5rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.column-body {
    flex: 1;
    min-height: 3rem;
}

.task-card {
    border-left: 3px solid #6c757d;
}

.priority-high {
    background-color: #dc3545 !important;
    color: #fff;
}

.priority-medium {
    background-color: #ffc107 !important;
    color: #212529;
}

.priority-low {
    background-color: #198754 !important;
    color: #fff;
}

